function Component({ items }) {
  // ❌ WITHOUT useMemo - runs every render
  const expensiveResult = items
    .filter(item => item.active)
    .map(item => item.value * 2)
    .reduce((sum, val) => sum + val, 0);

  // ✅ WITH useMemo - only runs when items changes
  const expensiveResult = useMemo(() => {
    console.log('Calculating...');
    return items
      .filter(item => item.active)
      .map(item => item.value * 2)
      .reduce((sum, val) => sum + val, 0);
  }, [items]);

  return <div>{expensiveResult}</div>;
}

function Component({ numbers, multiplier }) {
  const sum = useMemo(() => {
    console.log('Calculating...');
    return numbers.reduce((acc, n) => acc + n * multiplier, 0);
  }, [numbers, multiplier]); // Only recalculates when these change

  return <div>{sum}</div>;
}

// Now if parent re-renders but numbers and multiplier are the same,
// the calculation doesn't run - we use the cached value!

function Component({ userId, userName }) {
  // ❌ New object every render - breaks memoization
  const user = { id: userId, name: userName };

  useEffect(() => {
    fetchData(user); // Runs every render!
  }, [user]); // user is new object each time

  // ✅ Stable object reference - only new when primitives change
  const user = useMemo(() => {
    return { id: userId, name: userName };
  }, [userId, userName]); // Only creates new object when these change

  useEffect(() => {
    fetchData(user); // Only runs when userId or userName changes!
  }, [user]);
}

function Parent() {
  const [count, setCount] = useState(0);

  // ❌ New function every render - child re-renders unnecessarily
  const handleClick = () => {
    console.log('Clicked');
  };

  // ✅ Stable function reference - child doesn't re-render
  const handleClick = useCallback(() => {
    console.log('Clicked');
  }, []); // No dependencies = never changes

  return <MemoizedChild onClick={handleClick} />;
}

const MemoizedChild = React.memo(function Child({ onClick }) {
  console.log('Child rendered');
  return <button onClick={onClick}>Click</button>;
});

function Component() {
  const [count, setCount] = useState(0);

  // ❌ STALE - captures initial count (0) forever
  const handleClick = useCallback(() => {
    console.log('Count is:', count); // Always logs 0!
  }, []); // count not in dependencies

  // ✅ CORRECT - recreates when count changes
  const handleClick = useCallback(() => {
    console.log('Count is:', count); // Logs current count
  }, [count]); // count in dependencies

  // ✅ BEST - uses updater, doesn't need count in deps
  const increment = useCallback(() => {
    setCount(c => c + 1); // Gets current value from React
  }, []); // No dependencies needed!
}
